'use client';
import { useRef } from 'react';
import { m, useReducedMotion, useScroll, useTransform } from 'motion/react';

export interface TimelineEntry { when?: string; what: string; where: string; details?: string[] }

export function Timeline({ entries }: { entries: TimelineEntry[] }) {
  const ref = useRef<HTMLOListElement>(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start 80%', 'end 60%'] });
  const scaleY = useTransform(scrollYProgress, [0, 1], [0, 1]);
  return (
    <ol ref={ref} className="timeline">
      <span className="tl-track" aria-hidden="true" />
      <m.span className="tl-line" aria-hidden="true" style={{ scaleY: reduce ? 1 : scaleY }} />
      {entries.map((e, i) => (
        <m.li key={i} className="tl-item"
          initial={reduce ? false : { opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }} transition={{ duration: 0.5 }}>
          <m.span className="tl-node" aria-hidden="true"
            initial={reduce ? false : { backgroundColor: '#160D2B', boxShadow: '0 0 0 rgba(168,85,247,0)' }}
            whileInView={{ backgroundColor: '#A855F7', boxShadow: '0 0 16px rgba(168,85,247,.8)' }}
            viewport={{ margin: '-45% 0px -45% 0px' }} />
          <div className="glass pad"><strong>{e.what}</strong><p className="tl-meta">{[e.where, e.when].filter(Boolean).join(', ')}</p>{e.details && <ul className="tl-details">{e.details.map(d => <li key={d}>{d}</li>)}</ul>}</div>
        </m.li>
      ))}
    </ol>
  );
}
