'use client';
import { useState, type FormEvent } from 'react';
import { ContactError, sendContact } from '@/lib/contact';

type State = { kind: 'idle' | 'loading' | 'success' | 'mailto' } | { kind: 'error'; message: string; fields?: Record<string, string[]> };

export function ContactForm() {
  const [state, setState] = useState<State>({ kind: 'idle' });
  async function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    const f = new FormData(form);
    const data = { name: String(f.get('name')), email: String(f.get('email')), subject: String(f.get('subject')),
      message: String(f.get('message')), website: String(f.get('website') ?? '') };
    setState({ kind: 'loading' });
    try { const r = await sendContact(data); form.reset(); setState({ kind: r === 'mailto' ? 'mailto' : 'success' }); }
    catch (err) {
      const a = err instanceof ContactError ? err : new ContactError('Something went wrong.');
      setState({ kind: 'error', message: a.message, fields: a.fields });
    }
  }
  const fe = (k: string) => (state.kind === 'error' ? state.fields?.[k]?.[0] : undefined);
  return (
    <form onSubmit={onSubmit} className="glass pad">
      {(['name', 'email', 'subject'] as const).map(k => (
        <label key={k} style={{ display: 'block', textTransform: 'capitalize' }}>{k}
          <input name={k} type={k === 'email' ? 'email' : 'text'} required maxLength={k === 'subject' ? 150 : 100} aria-invalid={!!fe(k)} />
          {fe(k) && <span className="err" role="alert">{fe(k)}</span>}
        </label>
      ))}
      <label style={{ display: 'block' }}>Message
        <textarea name="message" rows={5} required minLength={10} maxLength={3000} aria-invalid={!!fe('message')} />
        {fe('message') && <span className="err" role="alert">{fe('message')}</span>}
      </label>
      <input className="hp" name="website" tabIndex={-1} autoComplete="off" aria-hidden="true" />
      <button className="btn btn-primary" disabled={state.kind === 'loading'}>{state.kind === 'loading' ? 'Sending…' : 'Send message'}</button>
      <div aria-live="polite" style={{ marginTop: 12 }}>
        {state.kind === 'success' && <p style={{ color: 'var(--cyan)' }}>Thanks! Your message was received.</p>}
        {state.kind === 'mailto' && <p style={{ color: 'var(--cyan)' }}>Your email app should open with the message ready to send.</p>}
        {state.kind === 'error' && <p className="err">{state.message}</p>}
      </div>
    </form>
  );
}
